import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade } from './people';
import { Session } from './session';

export interface Rate {
  grade: Grade;
  /** The percent as text with two decimals. */
  pct: string;
  /** The day (yyyy-mm-dd) the rate applies from; null when it applies from the beginning of time. */
  from: string | null;
  /** The last day (yyyy-mm-dd) the rate applies; null when it has no end. */
  to: string | null;
  /** The sheet the rate is set on: 0 for this sheet, 1 for its parent, 2 for the parent's parent,
   *  and so on. */
  level: number;
  /** How many versions the rate has had; this is the newest, the one in force. */
  version: number;
}

/** What a candidate rate would change: how many open and pending claims would show a different
 *  due, and the sum of the differences as two-decimal text (negative when lower). */
export interface RatePreview {
  count: number;
  diff: string;
}

/** The percent of a grade's rate in force on a day: on this sheet, or else, when it has none in
 *  force on it, on the nearest ancestor that has (see {@link levelPctOn}); undefined when none has. */
export function pctOn(rates: Rate[], grade: Grade, day: string): string | undefined {
  const levels = [...new Set(rates.map((r) => r.level))].sort((a, b) => a - b);
  for (const level of levels) {
    const pct = levelPctOn(rates.filter((r) => r.level === level), grade, day);
    if (pct !== undefined) return pct;
  }
  return undefined;
}

/** The percent of a grade's rate in force on a day among the rates of one sheet: the rate with the
 *  latest from-date on or before it, or else the one with no from-date; undefined when the day is
 *  before every rate, or after the to-date of that rate. */
function levelPctOn(rates: Rate[], grade: Grade, day: string): string | undefined {
  let best: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > day)) continue;
    if (best === undefined || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  if (best?.to != null && best.to < day) return undefined;
  return best?.pct;
}

/** A percent with up to two decimals, 0.00 or more. */
export const PCT = /^\d{1,5}(\.\d{1,2})?$/;

/** Two-decimal text, which may be negative, as a whole number of hundredths. */
function hundredths(text: string): bigint {
  const negative = text.startsWith('-');
  const [whole, frac = ''] = (negative ? text.slice(1) : text).split('.');
  const n = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  return negative ? -n : n;
}

/** An amount's due at a percent: amount times pct divided by 100, rounded to two decimals half to
 *  even, or half up (away from zero) when `halfUp`, worked in whole numbers so no rounding creeps
 *  in; a negative amount has a negative due. Null when there is no rate. */
export function due(amount: string, pct: string | undefined, halfUp = false): string | null {
  if (pct === undefined) return null;
  return weighted(hundredths(amount) * hundredths(pct), halfUp);
}

/** Amounts each times a percent divided by 100, added up exactly and then rounded to two decimals
 *  half to even. */
export function weightedSum(parts: { amount: string; pct: string }[]): string {
  return weighted(parts.reduce((sum, x) => sum + hundredths(x.amount) * hundredths(x.pct), 0n), false);
}

/** A product of two hundredths (so in ten-thousandths of a hundredth) rounded to two-decimal text. */
function weighted(signed: bigint, halfUp: boolean): string {
  const exact = signed < 0n ? -signed : signed;
  let cents = exact / 10000n;
  const rest = exact % 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  const text = cents.toString().padStart(3, '0');
  return `${signed < 0n && cents > 0n ? '-' : ''}${text.slice(0, -2)}.${text.slice(-2)}`;
}

/** The larger of two two-decimal figures. */
export function atLeast(figure: string, floor: string): string {
  return hundredths(figure) < hundredths(floor) ? floor : figure;
}

// The rates for each grade on the active sheet.
@Injectable({ providedIn: 'root' })
export class Rates {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The rates set on the sheet (level 0), then those of its ancestors, nearest first. */
  list(sheetId: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheetId)));
  }

  /** Set a grade's rate from a day (null: from the beginning of time) through a day (null: no
   *  end), replacing the one the grade had for that from-date. */
  set(grade: Grade, pct: string, from: string | null, to: string | null): Promise<Rate> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheetId)}/${grade}`, { pct, from, to }, { headers: { 'X-User': user } }),
    );
  }

  /** Set a rate per line of grade,rate,from,to, all or none; how many were set. */
  importRates(text: string): Promise<{ set: number }> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<{ set: number }>(`${this.url(sheetId)}/import`, { text }, { headers: { 'X-User': user } }),
    );
  }

  /** Preview a candidate rate applying to a grade on every date; nothing is saved. */
  preview(grade: Grade, pct: string): Promise<RatePreview> {
    const sheetId = this.session.sheetId();
    if (!sheetId) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.get<RatePreview>(`${this.url(sheetId)}/${grade}/preview`, { params: { pct } }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Grade, Leave, Person, heldOn, retiredOn } from './people';
import { Rate, atLeast, due, pctOn } from './rates';
import { DatedValue, Graces, RoundingMode, STARTING_FLOOR, STARTING_LATE_PCT, graceOn, valueOn } from './settings';
import { Session } from './session';

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a clerk's settle above the clerk
 *  limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
 *  DRAFT, OPEN or PENDING claim may be VOID, and a steward may void a SETTLED one within 7 days of
 *  its settlement. A DRAFT may be DELETED (counting nowhere), and restored to DRAFT the same day.
 *  Opening a claim whose due is above the review threshold leaves it in REVIEW (counting nowhere,
 *  with no number) until a steward reviews it (OPEN); a REVIEW claim may be VOID. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';

/** A change of status a claim can be asked for. */
export type ClaimAction = 'open' | 'settle' | 'resettle' | 'void' | 'approve' | 'reject' | 'delete' | 'restore'
  | 'review';

/** Whether a claim is open: OPEN, or PENDING approval of its settle. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim at this status counts toward claimed, due-total and every total. */
export function counts(c: Claim): boolean {
  return isOpen(c) || c.status === 'SETTLED';
}

/** Whether a claim is deferred on the sheet's today: it is OPEN and today is before the day it is
 *  deferred until. Until then it counts in no total, is not overdue and cannot be settled. */
export function deferred(c: Claim, today: string | null): boolean {
  return c.status === 'OPEN' && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/** Whether a claim counts in the live totals on the sheet's today: it counts, it is not deferred,
 *  and it is not an open (or pending) claim, unbound by a statement, dated within one of its
 *  person's holds or of a person retired on that day. */
export function countsLive(c: Claim, leave: Leave, today: string | null): boolean {
  return counts(c) && !deferred(c, today) && !leftOut(c, leave, today);
}

/** Whether the live rules leave a claim out: it is open (or pending), unbound by a statement, and
 *  dated within one of its person's holds or its person is retired on the sheet's today. */
function leftOut(c: Claim, leave: Leave, today: string | null): boolean {
  return isOpen(c) && !c.stated && (heldOn(leave.holds, c.date) || retiredOn(leave.retiredFrom, today));
}

/** The day (yyyy-mm-dd) a number of days after another (before it when negative). */
export function addDays(day: string, days: number): string {
  const d = new Date(day + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/** Whether a claim keeps its person active on the sheet's today: it is open (or pending), it
 *  counts in the live totals, and it is dated within the 30 days up to and including today. */
export function keepsActive(c: Claim, leave: Leave, today: string | null): boolean {
  return today !== null && isOpen(c) && countsLive(c, leave, today)
 *  pending (a pending claim shows its live figure). */
function bound(c: Claim): boolean {
  return c.stated && c.status !== 'PENDING';
}

/** Whether a claim keeps a figure that rates and grades no longer change: settled or bound by a
 *  statement. */
export function fixed(c: Claim): boolean {
  return c.settledDue !== null || (bound(c) && (c.statedDue !== null || c.statedNa));
}

/** What a claim's late charge follows: the sheet's today and its late percents (each 30-day boundary
 *  takes the one in force on it), and the grace days of each grade; and the sheet's rounding modes and
 *  policy date, which decide how its live figures round. */
export interface Lateness {
  today: string | null;
  /** The late percents recorded, each from its from-date, earliest first. */
  pcts: DatedValue[];
  /** The grace days recorded for each grade. */
  graces: Graces;
  /** The policy date set (yyyy-mm-dd); null when blank, the sheet's today then stands in. */
  policyDate: string | null;
  /** The rounding modes recorded (null: blank, none), each from its from-date, earliest first. */
  roundings: DatedValue<RoundingMode | null>[];
}

/** Whether a claim's live figures round half up: by the rounding mode in force on its date, or,
 *  when none is, when the date it rounds by is before the policy date in force (the one set, or
 *  else the sheet's today); otherwise they round half to even. */
export function roundsHalfUp(c: Claim, late: Lateness): boolean {
  const mode = valueOn<RoundingMode | null>(late.roundings, c.date, null);
  if (mode !== null) return mode === 'half-up';
  const policy = late.policyDate ?? late.today;
  return policy !== null && c.roundsBy < policy;
}

/** A claim's due figure: the one fixed when it was settled, or else the greater of the sheet's floor in force on the
 *  claim's date and its rate figure with the late charge on that figure on top while it is overdue. The rate figure is
 *  the one its person's last statement bound it to (n/a when it bound it to n/a), or else its live due at the rate in
 *  force on the claim's date for the grade (the person's grade in force on that date), rounded by the rounding mode or policy date (a
 *  settled claim's figure already holds the charge and the floor). A correction has no floor and no late charge. Null
 *  when there is none. */
export function claimDue(c: Claim, rates: Rate[], grade: Grade | undefined, floors: DatedValue[], late: Lateness): string | null {
  if (c.settledDue !== null) return c.settledDue;
  if (bound(c) && c.statedNa) return null;
  const live = due(c.amount, grade === undefined ? undefined : pctOn(rates, grade, c.date), roundsHalfUp(c, late));
  const figure = (bound(c) ? c.statedDue : null) ?? live;
  if (figure === null) return null;
  const charged = sumAmounts([figure, lateCharge(c, figure, late, grade)]);
  return correction(c) ? charged : atLeast(charged, valueOn(floors, c.date, STARTING_FLOOR));
}

/** The late charge on an overdue claim (its grade being its person's grade in force on its date): for each full
 *  30 days it is overdue, the late percent in force on that boundary (its late-from plus 30, 60, 90 ... days) of its
 *  figure plus the charges of the boundaries before it (the charge compounds), rounded like a due, the charges added
 *  up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue, and on a correction. */
export function lateCharge(c: Claim, figure: string, late: Lateness, grade: Grade | undefined): string {
  if (correction(c)) return '0.00';
  const grace = graceOn(late.graces, grade, c.date);
  if (!overdue(c, late.today, grace) || late.today === null) return '0.00';
  const from = Date.parse(lateFrom(c, grace));
